pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        c = new C();
        admin = msg.sender;
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != admin);
        vm.prank(actor);
        try c.setOwner(newOwner) {
            // only admin may change the owner
            assertTrue(c.owner() == c.owner());
        } catch {
            // call reverted, owner untouched
        }
        // general rule: setOwner only succeeds for the admin; owner must equal admin (deployer) afterwards
        assertTrue(c.owner() != address(0) && (c.owner() == newOwner ? actor == admin : true));
    }
}

