pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        c = new C();
        admin = address(this); // deployer of C == msg.sender at construction == admin/owner
    }

    function testFuzz_property(address newOwner) public {
        // The caller must be the admin so the call completes (does not revert).
        // The new owner is entirely fuzzed: it may equal or differ from the current owner.
        vm.prank(admin);
        bool success = c.setOwner(newOwner);

        // General rule: a completed setOwner by the admin ALWAYS reports success (true),
        // regardless of whether the new owner differs from the old one.
        // The mutant returns owner == _owner, i.e. false whenever newOwner != old owner.
        assertTrue(success);
    }
}

