pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        admin = msg.sender;
        c = new C();
    }

    function testFuzz_property(address caller, address newOwner) public {
        // Wide admissible domain: only require the caller to be the admin so the
        // call completes in both versions; the new owner is completely unconstrained
        // (zero address, weird addresses, current owner, anything).
        vm.assume(caller == admin);

        vm.prank(caller);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("setOwner(address)", newOwner)
        );

        // General rule: for ANY admissible input the call completes (does not revert),
        // reports success=true, carries exactly one bool return value, and that decoded
        // return value is unconditionally true (success is not conditional on the state).
        assertTrue(
            ok && ret.length == 32 && abi.decode(ret, (bool)),
            "completed setOwner must unconditionally report success"
        );
    }
}

